class Fan {

    int wings;
    String color;
    int cost;
    String brand;

    Fan(int wings, String color, int cost, String brand) {
        this.wings = wings;
        this.color = color;
        this.cost = cost;
        this.brand = brand;
    }

    void rotate() {
        System.out.println(
            brand + " fan with " + color + " color is rotating"
        );
    }

    void giveAir() {
        System.out.println(
            brand + " fan with " + color + " color is giving air"
        );
    }
}

public class Main {

    public static void main(String[] args) {

        Fan fan = new Fan(2, "Red", 6000, "Usha");

        System.out.println(
            fan.wings + " " +
            fan.color + " " +
            fan.cost + " " +
            fan.brand
        );

        fan.rotate();
        fan.giveAir();
    }
}

